const chatInput = String($('Receber Mensagem').item.json.chatInput ?? '').trim();

const normalizar = (texto) => String(texto ?? '')
  .normalize('NFD')
  .replace(/[\u0300-\u036f]/g, '')
  .trim();

const msg = normalizar(chatInput).toLowerCase();
const raw = normalizar($json.output)
  .replace(/```[a-z]*|```/gi, '')
  .toUpperCase();

let intent = 'OUTRO';

if (/\bAUTORIZACAO\b/.test(raw)) {
  intent = 'AUTORIZACAO';
} else if (/\bCONSULTA\b/.test(raw)) {
  intent = 'CONSULTA';
} else if (/\bOUTRO\b/.test(raw)) {
  intent = 'OUTRO';
}

// Regras determinísticas para respostas curtas comuns de autorização.
// Elas funcionam como uma camada de segurança caso a IA classifique uma
// resposta como "pessoal" ou "14:30" incorretamente como OUTRO.
const consultaExplicita = /(historico|consultar|consulte|consulta de historico|ver (as )?saidas|saidas de|pesquisar historico|buscar historico)/i.test(msg);
const autorizacaoExplicita = /(autoriz|liber|pode sair|nao pode sair|nao libero|nao autor|permito|permissao para sair)/i.test(msg);

const pareceHorario = /^(?:[01]?\d|2[0-3])\s*(?::|h)\s*[0-5]\d$/.test(msg);
const pareceData = /^(?:0?[1-9]|[12]\d|3[01])[\/\-](?:0?[1-9]|1[0-2])(?:[\/\-]\d{2,4})?$/.test(msg) || /^(hoje|amanha)$/.test(msg);

const motivosComuns = /^(pessoal|motivo pessoal|facepe|consulta|consulta medica|medico|medica|dentista|exame|terapia|saude|doenca|compromisso|compromisso familiar|familiar|trabalho|viagem|documentos|assunto pessoal|emergencia|emergencia familiar)$/i;
const pareceMotivo = motivosComuns.test(msg);

if (consultaExplicita) {
  intent = 'CONSULTA';
} else if (autorizacaoExplicita || pareceHorario || pareceData || pareceMotivo) {
  intent = 'AUTORIZACAO';
}

return [
  {
    json: {
      intent,
      intent_original: $json.output ?? '',
      chatInput,
      classificacao_protegida: pareceHorario || pareceData || pareceMotivo
    }
  }
];

function parseSaidaIA(valor) {
  if (valor && typeof valor === 'object') return valor;

  const texto = String(valor ?? '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();

  try {
    return JSON.parse(texto);
  } catch (e) {
    const bloco = texto.match(/\{[\s\S]*\}/);
    if (bloco) {
      try { return JSON.parse(bloco[0]); } catch (_) {}
    }
    throw new Error('JSON inválido retornado pela IA');
  }
}

function semAcentos(texto) {
  return String(texto ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '');
}

function ausente(valor) {
  const v = semAcentos(valor).trim().toLowerCase();
  return !v || v === 'nao informado' || v === 'null' || v === 'undefined';
}

function limpar(valor) {
  return ausente(valor) ? 'Não informado' : String(valor).trim().replace(/\s+/g, ' ');
}

function hojeRecife(offsetDias = 0) {
  const partes = new Intl.DateTimeFormat('en-GB', {
    timeZone: 'America/Recife',
    day: '2-digit', month: '2-digit', year: 'numeric'
  }).formatToParts(new Date());

  const obj = Object.fromEntries(partes.filter(p => p.type !== 'literal').map(p => [p.type, p.value]));
  const base = new Date(Date.UTC(Number(obj.year), Number(obj.month) - 1, Number(obj.day)));
  base.setUTCDate(base.getUTCDate() + offsetDias);

  return {
    dia: String(base.getUTCDate()).padStart(2, '0'),
    mes: String(base.getUTCMonth() + 1).padStart(2, '0'),
    ano: String(base.getUTCFullYear())
  };
}

function normalizarTurma(valor) {
  if (ausente(valor)) return null;

  let t = semAcentos(valor)
    .toUpperCase()
    .replace(/[º°ª]/g, '')
    .replace(/[-_.]/g, ' ')
    .replace(/\bPRIMEIRO\b/g, '1')
    .replace(/\bSEGUNDO\b/g, '2')
    .replace(/\bTERCEIRO\b/g, '3')
    .replace(/\bANO\b/g, ' ')
    .replace(/\bDESENVOLVIMENTO\s+DE\s+SISTEMAS\b/g, 'DS')
    .replace(/\bDESENVOLVIMENTO\s+SISTEMAS\b/g, 'DS')
    .replace(/\bADMINISTRACAO\b/g, 'ADM')
    .replace(/\s+/g, ' ')
    .trim();

  const match = t.match(/^([123])\s*(DS|ADM)\s*([AB])$/);
  if (!match) return null;
  return `${match[1]} ${match[2]} ${match[3]}`;
}

function normalizarData(valor) {
  if (ausente(valor)) return null;

  const bruto = semAcentos(valor).trim().toLowerCase();
  if (bruto === 'hoje') {
    const d = hojeRecife(0);
    return `${d.dia}/${d.mes}/${d.ano}`;
  }
  if (bruto === 'amanha') {
    const d = hojeRecife(1);
    return `${d.dia}/${d.mes}/${d.ano}`;
  }

  const atual = hojeRecife(0);
  const m = bruto.replace(/[.\-]/g, '/').match(/^(\d{1,2})\/(\d{1,2})(?:\/(\d{2,4}))?$/);
  if (!m) return null;

  const dia = Number(m[1]);
  const mes = Number(m[2]);
  let ano = m[3] ? Number(m[3]) : Number(atual.ano);
  if (ano < 100) ano += 2000;

  const teste = new Date(Date.UTC(ano, mes - 1, dia));
  if (
    teste.getUTCFullYear() !== ano ||
    teste.getUTCMonth() !== mes - 1 ||
    teste.getUTCDate() !== dia
  ) return null;

  return `${String(dia).padStart(2, '0')}/${String(mes).padStart(2, '0')}/${ano}`;
}

function normalizarHorario(valor) {
  if (ausente(valor)) return null;

  let h = semAcentos(valor).trim().toLowerCase().replace(/\s+/g, '');
  h = h.replace(/h/g, ':').replace(/\./g, ':').replace(/:+$/, '');

  const m = h.match(/^(\d{1,2})(?::(\d{1,2}))?$/);
  if (!m) return null;

  const hora = Number(m[1]);
  const minuto = m[2] === undefined ? 0 : Number(m[2]);
  if (hora < 0 || hora > 23 || minuto < 0 || minuto > 59) return null;

  return `${String(hora).padStart(2, '0')}:${String(minuto).padStart(2, '0')}`;
}

function normalizarStatus(valor) {
  if (ausente(valor)) return 'Não informado';
  const s = semAcentos(valor).trim().toLowerCase();

  if (/nao\s*(autoriz|liber|permit)|negad|nao pode/.test(s)) return 'Negado';
  if (/autoriz|liberad|permitid|pode sair|^sim$/.test(s)) return 'Autorizado';
  return 'Não informado';
}

let dados;
let erroProcessamento = false;
let mensagemErro = '';

try {
  dados = parseSaidaIA($json.output);
} catch (e) {
  erroProcessamento = true;
  mensagemErro = e.message;
  dados = {};
}

const erros = [];

dados.nome_aluno = limpar(dados.nome_aluno);
dados.responsavel = limpar(dados.responsavel);
dados.motivo = limpar(dados.motivo);

if (ausente(dados.turma)) {
  dados.turma = 'Não informado';
} else {
  const turma = normalizarTurma(dados.turma);
  if (turma) dados.turma = turma;
  else {
    dados.turma = 'Não informado';
    erros.push('turma_invalida');
  }
}

if (ausente(dados.data_saida)) {
  dados.data_saida = 'Não informado';
} else {
  const data = normalizarData(dados.data_saida);
  if (data) dados.data_saida = data;
  else {
    dados.data_saida = 'Não informado';
    erros.push('data_invalida');
  }
}

if (ausente(dados.horario_saida)) {
  dados.horario_saida = 'Não informado';
} else {
  const horario = normalizarHorario(dados.horario_saida);
  if (horario) dados.horario_saida = horario;
  else {
    dados.horario_saida = 'Não informado';
    erros.push('horario_invalido');
  }
}

dados.status = normalizarStatus(dados.status);

const obrigatorios = [
  'nome_aluno', 'turma', 'responsavel',
  'data_saida', 'horario_saida', 'motivo'
];

const camposCompletos = obrigatorios.every(c => dados[c] && dados[c] !== 'Não informado');

dados.autorizacao_valida = camposCompletos && dados.status === 'Autorizado' && !erroProcessamento && erros.length === 0;
dados.erros_validacao = erros;
dados.erro_processamento = erroProcessamento;
dados.mensagem_erro = mensagemErro;

dados.data_registro = new Date().toLocaleString('pt-BR', {
  timeZone: 'America/Recife'
});

return [{ json: dados }];

const dados = $input.first().json;

const mensagem =
`AUTORIZAÇÃO REGISTRADA

Aluno: ${dados.nome_aluno || "Não informado"}
Turma: ${dados.turma || "Não informado"}
Responsável: ${dados.responsavel || "Não informado"}
Data da saída: ${dados.data_saida || "Não informado"}
Horário: ${dados.horario_saida || "Não informado"}
Motivo: ${dados.motivo || "Não informado"}
Status: ${dados.status || "Autorizado"}

Registro realizado com sucesso.`;

return [
  {
    json: {
      output: mensagem
    }
  }
];

const dados = $input.first().json;

if (dados.erro_processamento) {
  return [{
    json: {
      ...dados,
      campo_faltante: null,
      output: 'Não consegui interpretar os dados da autorização com segurança. Por favor, envie novamente a autorização em uma frase mais clara.'
    }
  }];
}

if (dados.status === 'Negado') {
  return [{
    json: {
      ...dados,
      campo_faltante: null,
      output: 'Entendi. A saída NÃO foi registrada porque a mensagem indica que o responsável não autorizou o aluno a sair.'
    }
  }];
}

const erros = Array.isArray(dados.erros_validacao) ? dados.erros_validacao : [];

if (erros.includes('turma_invalida')) {
  return [{ json: { ...dados, campo_faltante: 'turma', output: 'A turma informada não é válida. Informe uma turma como 1 ADM A, 2 DS B ou 3 DS A.' } }];
}
if (erros.includes('data_invalida')) {
  return [{ json: { ...dados, campo_faltante: 'data_saida', output: 'A data informada não é válida. Informe a data no formato DD/MM/AAAA, ou use “hoje” ou “amanhã”.' } }];
}
if (erros.includes('horario_invalido')) {
  return [{ json: { ...dados, campo_faltante: 'horario_saida', output: 'O horário informado não é válido. Informe um horário entre 00:00 e 23:59, por exemplo 14:30.' } }];
}

const campos = [
  { campo: 'nome_aluno', pergunta: 'Qual é o nome completo do aluno?' },
  { campo: 'turma', pergunta: `Qual é a turma de ${dados.nome_aluno && dados.nome_aluno !== 'Não informado' ? dados.nome_aluno : 'aluno'}?` },
  { campo: 'responsavel', pergunta: 'Qual é o nome do responsável que está autorizando a saída?' },
  { campo: 'data_saida', pergunta: 'Qual é a data da saída?' },
  { campo: 'horario_saida', pergunta: 'Qual será o horário da saída?' },
  { campo: 'motivo', pergunta: 'Qual é o motivo da saída?' }
];

const faltando = campos.find(item => {
  const valor = dados[item.campo];
  const normalizado = String(valor ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim()
    .toLowerCase();
  return !normalizado || normalizado === 'nao informado';
});

if (faltando) {
  return [{
    json: {
      ...dados,
      campo_faltante: faltando.campo,
      output: faltando.pergunta
    }
  }];
}

if (dados.status !== 'Autorizado') {
  return [{
    json: {
      ...dados,
      campo_faltante: 'status',
      output: `Os dados estão completos. Você confirma que autoriza ${dados.nome_aluno} a sair no dia ${dados.data_saida} às ${dados.horario_saida}?`
    }
  }];
}

return [{
  json: {
    ...dados,
    campo_faltante: null,
    output: 'Não foi possível concluir a autorização. Revise os dados e tente novamente.'
  }
}];

function parseSaidaIA(valor) {
  if (valor && typeof valor === 'object') return valor;
  const texto = String(valor ?? '')
    .replace(/```json/gi, '')
    .replace(/```/g, '')
    .trim();
  try {
    return JSON.parse(texto);
  } catch (e) {
    const bloco = texto.match(/\{[\s\S]*\}/);
    if (bloco) {
      try { return JSON.parse(bloco[0]); } catch (_) {}
    }
    throw new Error('JSON inválido retornado pela IA');
  }
}

function semAcentos(texto) {
  return String(texto ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '');
}

function ausente(valor) {
  const v = semAcentos(valor).trim().toLowerCase();
  return !v || v === 'nao informado' || v === 'null' || v === 'undefined';
}

function titulo(texto) {
  return String(texto)
    .trim()
    .toLowerCase()
    .replace(/(^|\s)\S/g, letra => letra.toUpperCase())
    .replace(/\s+/g, ' ');
}

function normalizarTurma(valor) {
  if (ausente(valor)) return null;
  let t = semAcentos(valor)
    .toUpperCase()
    .replace(/[º°ª]/g, '')
    .replace(/[-_.]/g, ' ')
    .replace(/\bPRIMEIRO\b/g, '1')
    .replace(/\bSEGUNDO\b/g, '2')
    .replace(/\bTERCEIRO\b/g, '3')
    .replace(/\bANO\b/g, ' ')
    .replace(/\bDESENVOLVIMENTO\s+DE\s+SISTEMAS\b/g, 'DS')
    .replace(/\bDESENVOLVIMENTO\s+SISTEMAS\b/g, 'DS')
    .replace(/\bADMINISTRACAO\b/g, 'ADM')
    .replace(/\s+/g, ' ')
    .trim();
  const m = t.match(/^([123])\s*(DS|ADM)\s*([AB])$/);
  return m ? `${m[1]} ${m[2]} ${m[3]}` : null;
}

let dados;
let erroProcessamento = false;

try {
  dados = parseSaidaIA($json.output);
} catch (e) {
  dados = {};
  erroProcessamento = true;
}

dados.nome_aluno = ausente(dados.nome_aluno) ? 'Não informado' : titulo(dados.nome_aluno);

if (ausente(dados.turma)) {
  dados.turma = 'Não informado';
} else {
  const turma = normalizarTurma(dados.turma);
  dados.turma = turma || 'Não informado';
  if (!turma) dados.turma_invalida = true;
}

dados.erro_processamento = erroProcessamento;

return [{ json: dados }];

const entrada = $input.all();

// Se o nó anterior já produziu uma resposta final (nenhum resultado,
// consulta ambígua etc.), preserve essa mensagem.
if (
  entrada.length === 1 &&
  entrada[0].json &&
  entrada[0].json.finalizar_consulta &&
  entrada[0].json.output
) {
  return [{
    json: {
      ...entrada[0].json,
      output: entrada[0].json.output
    }
  }];
}

let registros = [];

// Aceita registros separados ou vindos do nó "Analisar Turmas".
if (
  entrada.length === 1 &&
  Array.isArray(entrada[0].json.registros)
) {
  registros = entrada[0].json.registros;
} else {
  registros = entrada
    .map(item => item.json)
    .filter(r => r && r.nome_aluno && r.data_saida);
}

// Sem resultados.
if (registros.length === 0) {
  return [{
    json: {
      output:
`**AUTORIZAIA**

### HISTÓRICO DE SAÍDAS

Nenhum registro foi encontrado para o aluno informado.

Verifique o nome e a turma e tente novamente.`
    }
  }];
}

// Remove registros idênticos duplicados apenas da exibição.
const vistos = new Set();
registros = registros.filter(r => {
  const chave = [
    r.nome_aluno,
    r.turma,
    r.data_saida,
    r.horario_saida,
    r.responsavel,
    r.motivo,
    r.status
  ].map(v => String(v ?? '').trim()).join('|');

  if (vistos.has(chave)) return false;
  vistos.add(chave);
  return true;
});

function limpar(valor) {
  if (valor === undefined || valor === null || String(valor).trim() === '') {
    return 'Não informado';
  }

  // Evita quebrar a tabela Markdown caso algum valor contenha "|".
  return String(valor)
    .trim()
    .replace(/\|/g, '\\|');
}

function primeiraMaiuscula(valor) {
  const texto = limpar(valor);
  if (texto === 'Não informado') return texto;
  return texto.charAt(0).toUpperCase() + texto.slice(1);
}

const nome = limpar(registros[0].nome_aluno);
const turmas = [...new Set(
  registros
    .map(r => limpar(r.turma))
    .filter(t => t !== 'Não informado')
)];

const turmaCabecalho = turmas.length === 0
  ? 'Não informado'
  : turmas.join(', ');

let mensagem =
`**AUTORIZAIA**

### HISTÓRICO DE SAÍDAS

| Informação | Valor |
| :--- | :--- |
| Aluno | ${nome} |
| Turma | ${turmaCabecalho} |
| Registros encontrados | ${registros.length} |`;

registros.forEach((r, index) => {
  const numero = String(index + 1).padStart(2, '0');

  mensagem += `

### REGISTRO ${numero}

| Campo | Valor |
| :--- | :--- |
| Data | ${limpar(r.data_saida)} |
| Horário | ${limpar(r.horario_saida)} |
| Turma | ${limpar(r.turma)} |
| Responsável | ${limpar(r.responsavel)} |
| Motivo | ${primeiraMaiuscula(r.motivo)} |
| Status | ${limpar(r.status)} |`;
});

mensagem += `

---

Consulta concluída pelo **AutorizaIA**.`;

return [{
  json: {
    output: mensagem
  }
}];

const registros = $input.all().filter(item => item.json && item.json.nome_aluno);
const consulta = $('Padronizar Dados da Consulta').first().json;

function normalizar(texto) {
  return String(texto || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function limparMarkdown(valor) {
  return String(valor ?? '')
    .trim()
    .replace(/\|/g, '\\|');
}

const nomeBuscado = normalizar(consulta.nome_aluno);
const turmaBuscada = normalizar(consulta.turma);

let encontrados = registros.filter(item => {
  const nome = normalizar(item.json.nome_aluno);
  const turma = normalizar(item.json.turma);

  const nomeCombina =
    nome.includes(nomeBuscado) ||
    nomeBuscado.includes(nome);

  return nomeCombina && turma === turmaBuscada;
});

if (encontrados.length === 0) {
  return [{
    json: {
      tipo_resultado: 'nenhum',
      finalizar_consulta: true,
      output:
`**AUTORIZAIA**

### HISTÓRICO DE SAÍDAS

Nenhum registro foi encontrado para **${limparMarkdown(consulta.nome_aluno)}** na turma **${limparMarkdown(consulta.turma)}**.

Verifique os dados e tente novamente.`
    }
  }];
}

// Correspondência exata tem prioridade.
const exatos = encontrados.filter(
  item => normalizar(item.json.nome_aluno) === nomeBuscado
);

if (exatos.length > 0) {
  encontrados = exatos;
}

// Descobre quantas pessoas diferentes ainda correspondem.
const pessoas = new Map();

for (const item of encontrados) {
  const nomeOriginal = String(item.json.nome_aluno || '').trim();
  const chave = normalizar(nomeOriginal);

  if (!pessoas.has(chave)) {
    pessoas.set(chave, {
      nome: nomeOriginal,
      registros: []
    });
  }

  pessoas.get(chave).registros.push(item);
}

if (pessoas.size > 1) {
  const nomes = [...pessoas.values()]
    .map(p => p.nome)
    .sort((a, b) => a.localeCompare(b, 'pt-BR'));

  let mensagem =
`**AUTORIZAIA**

### CONSULTA AMBÍGUA

Encontrei mais de um aluno correspondente a **${limparMarkdown(consulta.nome_aluno)}** na turma **${limparMarkdown(consulta.turma)}**.

| Aluno | Turma |
|---|---|`;

  for (const nome of nomes) {
    mensagem += `\n| ${limparMarkdown(nome)} | ${limparMarkdown(consulta.turma)} |`;
  }

  mensagem += `

Informe **o nome completo** do aluno que deseja consultar.`;

  return [{
    json: {
      tipo_resultado: 'ambiguo_mesma_turma',
      finalizar_consulta: true,
      nomes,
      turma: consulta.turma,
      output: mensagem
    }
  }];
}

// Uma única pessoa: retorna todos os registros dela.
return [...pessoas.values()][0].registros;

const consulta = $('Padronizar Dados da Consulta').first().json;
const registros = $input.all().filter(item => item.json && item.json.nome_aluno);

function normalizar(texto) {
  return String(texto || '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]/g, '');
}

function limparMarkdown(valor) {
  return String(valor ?? '')
    .trim()
    .replace(/\|/g, '\\|');
}

const termo = normalizar(consulta.nome_aluno);

let encontrados = registros.filter(item => {
  const nome = normalizar(item.json.nome_aluno);
  return nome.includes(termo) || termo.includes(nome);
});

if (encontrados.length === 0) {
  return [{
    json: {
      tipo_resultado: 'nenhum',
      finalizar_consulta: true,
      output:
`**AUTORIZAIA**

### HISTÓRICO DE SAÍDAS

Nenhum registro foi encontrado para o aluno informado.

Verifique o nome e tente novamente.`
    }
  }];
}

// Se houver correspondência exata, ela tem prioridade sobre nomes apenas parecidos.
const exatos = encontrados.filter(
  item => normalizar(item.json.nome_aluno) === termo
);

if (exatos.length > 0) {
  encontrados = exatos;
}

// Agrupa cada pessoa por nome normalizado e reúne as turmas em que ela aparece.
const pessoas = new Map();

for (const item of encontrados) {
  const nomeOriginal = String(item.json.nome_aluno || '').trim();
