  if (!pessoas.has(chave)) {
    pessoas.set(chave, {
      nome: nomeOriginal,
      turmas: new Set(),
      registros: []
    });
  }

  pessoas.get(chave).turmas.add(turma);
  pessoas.get(chave).registros.push(item);
}

